const keptPartnerIDs = `-- name: KeptPartnerIDs :many
SELECT id FROM partners WHERE project_id = ?1 AND is_deleted = 0 AND id IN (/*SLICE:ids*/?)
`

type KeptPartnerIDsParams struct {
	ProjectID uuid.UUID
	Ids       []uuid.UUID
}

// Which of a project's partners, not deleted, these are.
func (q *Queries) KeptPartnerIDs(ctx context.Context, arg KeptPartnerIDsParams) ([]uuid.UUID, error) {
	query := keptPartnerIDs
	var queryParams []interface{}
	queryParams = append(queryParams, arg.ProjectID)
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.query(ctx, nil, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

